# Amnezia Care installer 1.0; no remote downloads or telemetry.
#requires -Version 5.1
$ErrorActionPreference = 'Stop'
$p = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Start-Process powershell.exe -Verb RunAs -Wait -ArgumentList @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", "`"$PSCommandPath`"")
    exit
}
$destination = Join-Path $env:LOCALAPPDATA 'AmneziaCare\tool'
New-Item -ItemType Directory -Path $destination -Force | Out-Null
[IO.File]::WriteAllBytes((Join-Path $destination 'Care.ps1'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $destination 'server-check.sh'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $destination 'Start.cmd'), [Convert]::FromBase64String('QGVjaG8gb2ZmCmNkIC9kICIlfmRwMCIKcG93ZXJzaGVsbC5leGUgLU5vUHJvZmlsZSAtRXhlY3V0aW9uUG9saWN5IEJ5cGFzcyAtRmlsZSAiJX5kcDBDYXJlLnBzMSIKcGF1c2UKCg=='))
[IO.File]::WriteAllBytes((Join-Path $destination 'README.md'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $destination 'CASE-STUDY.md'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $destination 'PROMPT.md'), [Convert]::FromBase64String(''))
New-Item -ItemType Directory -Path (Join-Path $destination 'assets') -Force | Out-Null
[IO.File]::WriteAllBytes((Join-Path $destination 'assets/amnezia-care.svg'), [Convert]::FromBase64String(''))
Write-Host "Installed: $destination" -ForegroundColor Green
& (Join-Path $destination 'Care.ps1')


